mapper.select:
SELECT
    MAX(high_price) AS high,
    MIN(low_price)  AS low,
    (
        SELECT close_price
        FROM stock_price_daily
        WHERE stock_code = #{stockCode}
          AND trade_date BETWEEN #{fromDate} AND #{toDate}
        ORDER BY trade_date DESC
        LIMIT 1
    ) AS last_close
FROM stock_price_daily
WHERE stock_code = #{stockCode}
  AND trade_date BETWEEN #{fromDate} AND #{toDate}
